class PartialInformationEvidenceTests(unittest.TestCase):
 @classmethod
 def setUpClass(cls):cls.data=r.p.read(r.DEFAULT)
 def reject(self,d):
  with self.assertRaises((ValueError,KeyError,TypeError,AssertionError)):r.replay(d)
 def test_actual_closed_read_only_counters_and_nested_denominators_replay_without_models(self):
  with patch('runaway.generation.codex_generate',side_effect=AssertionError('No service'))as backend:o=r.check()
  backend.assert_not_called()
  for k in ('actual_original_attempts','actual_original_children','known_original_usage','missing_original_usage','unused_slots_expire','summary'):self.assertEqual(o[k],EXPECTED[k])
  self.assertEqual(o['new_extractions'],0);self.assertEqual(len(o['fixed_parents']),8)
  for v in r.p.VIEWS:
   self.assertEqual(o['summary']['joint'][v]['joint']['planned'],64)
   self.assertEqual(o['summary']['primary'][v]['joint']['planned'],48)
   self.assertEqual(o['summary']['primary'][v]['known']['planned'],16)
   self.assertEqual(o['summary']['primary'][v]['unknown']['planned'],32)
   self.assertEqual(o['summary']['anchors'][v]['joint']['planned'],16)
 def test_fixed_sources_parents_questions_and_reference_derivation_cannot_change(self):
  for name in ('sources.json','parents.public.json','queries.public.json','reference.private.json','reference-derivation.private.json','implementation-sha256.json'):
   d=copy.deepcopy(self.data);d['prepared_files'][name]={};self.reject(d)
  for name in ('scientific_source_ref','input_manifest_sha256'):
   d=copy.deepcopy(self.data);d[name]='foreign';self.reject(d)
 def test_old_parent_versions_cannot_be_relabelled_or_claimed_as_new_extractions(self):
  d=copy.deepcopy(self.data);d['records'].append(copy.deepcopy(d['records'][0]));self.reject(d)
  d=copy.deepcopy(self.data);d['records'][0]['profile']='foreign';d['records'][0]['execution_record']['profile']='foreign';self.reject(d)
  for value in (1,False):
   d=copy.deepcopy(self.data);d['status']['new_extractions']=value;self.reject(d)
  d=copy.deepcopy(self.data);d['records'][0]['artifact']={'prompt':'invented new card'};self.reject(d)
 def test_raw_values_and_changed_known_or_unknown_answers_are_not_accepted_as_original(self):
  d=copy.deepcopy(self.data);rec=next((x for x in d['records']if x['raw_present']),None)
  if rec is None:d['records'][0]['raw']='invented'
  else:rec['raw']+='changed'
  self.reject(d)
  for known in (True,False):
   d=copy.deepcopy(self.data);rec=next((x for x in d['records']if x['kind']=='read'and x['raw_present']),None)
   if rec is None:self.assertEqual(self.data['status']['scores']['primary']['card']['joint']['missing'],48);continue
   row=next(x for x in r.p.inputs()['rows']if x['person']==rec['profile']and x['primary']and(x['gold']!='U')==known)
   answer=r.e.parse_answer(rec['raw']);q=row['query_ids'][0]
   options=next(x['options']for x in r.p.inputs()['queries']['all']if x['id']==q)
   answer[q]=next(iter(options.values()))if answer[q]=='U'else'U'
   rec['raw']=json.dumps(answer,ensure_ascii=False);rec['raw_value_sha256']=r.p.digest(rec['raw']);self.reject(d)
 def test_primary_known_unknown_and_anchor_denominators_cannot_be_pooled_or_shrunk(self):
  for group,metric in [('primary','joint'),('primary','known'),('primary','unknown'),('anchors','joint'),('joint','joint')]:
   d=copy.deepcopy(self.data);d['status']['scores'][group]['card'][metric]['planned']-=1;self.reject(d)
  d=copy.deepcopy(self.data);d['status']['scope_closed']=False;self.reject(d)
 def test_tail_and_same_parent_requests_cannot_be_swapped_or_modified(self):
  d=copy.deepcopy(self.data);rec=next((x for x in d['records']if x['kind']=='read'),d['records'][0])
  rec['request']['prompt']+='foreign material';rec['request_sha256']=r.p.digest(rec['request']);rec['execution_record']['request_sha256']=rec['request_sha256'];self.reject(d)
  d=copy.deepcopy(self.data);rec=next((x for x in d['records']if x['kind']=='read'),d['records'][0]);rec['read_repeat']=9;rec['execution_record']['read_repeat']=9;self.reject(d)
 def test_usage_attempts_and_child_intents_cannot_be_rewritten(self):
  for fault in ('usage','attempt','child'):
   d=copy.deepcopy(self.data)
   if fault=='usage':d['status']['known_usage']['total_tokens']=d['status']['known_usage'].get('total_tokens',0)+1
   elif fault=='attempt':d['status']['attempt_reservations']-=1
   else:d['records'][0]['local_cli_child_intent']=not d['records'][0]['local_cli_child_intent']
   self.reject(d)
 def test_unsupported_fidelity_or_private_fields_are_rejected(self):
  for field in r.FALSE_CLAIMS:
   d=copy.deepcopy(self.data);d[field]=True;self.reject(d)
  d=copy.deepcopy(self.data);d['human_grant']='PRIVATE';self.reject(d)
  d=copy.deepcopy(self.data);d['records'][0]['runtime_path']='PRIVATE';self.reject(d)
 def test_loss_classes_keep_missing_distinct_from_uncertainty(self):
  for gold,values,expected in [('A',[None,'U'],'missing'),('A',['U','U'],'all_unknown_from_known'),('A',['A','U'],'intermittent_unknown_from_known'),('A',['A','B'],'different_choice_from_known'),('U',['U','A'],'choice_when_reference_unknown'),('U',['U','U'],'retained')]:self.assertEqual(r.loss_kind(gold,values),expected)
  with self.assertRaises(ValueError):r.loss_kind('A',[])
if __name__=='__main__':unittest.main()
